/* Extended design review only: no auth service, model, Agent, MCP, database or code access. */
(() => {
  'use strict';
  const root=document.querySelector('#configuration-root');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pages={integrations:['模型、ACP 与 MCP','分清模型账号、Agent 执行连接和工具服务，先检查接入条件。'],runtime:['执行环境与代码','区分业务环境、Agent 宿主和代码快照，明确真实访问限制。'],context:['上下文与记忆','按来源和权限组装本轮材料，长期记忆需单独审核。'],users:['用户与权限','按可管理范围维护成员状态与授权；以下都是合成身份。'],records:['用户记录','按范围审阅合成问题、执行事实和资料；正文需要用途授权。']};
  const settings={auth:'agent_managed',acpVersion:'v1',mcpVersion:'2026-07-28',transport:'streamable-http',readCode:true,writeCode:false,terminal:false,network:'allowlist',isolation:'unverified',codeCommit:'demo-commit-a',deployment:'demo-commit-a',memory:'off',contextLimit:16000,outputReserve:4000};
  const J=window.ReviewJourney,users=J.users;
  const records=[{id:'demo-record-1',owner:'demo-tester',scope:'orders-test',title:'报表与明细差异（合成）',status:'待验证',text:'合成提问：报表金额和明细金额不一致。\n合成助手：请对齐时间与状态，再核对证据。本例尚待用户确认。',usage:'未上报实际费用',events:['用户条件已保存','唯一执行绑定：demo-binding-record-1','只读授权已确认（合成）','上下文清单已固定（合成）','合成结果已交付，待用户验证']},{id:'demo-record-2',owner:'demo-collaborator',scope:'orders-test',title:'接口超时核查（合成）',status:'核查中',text:'合成请求发生超时。必须核查原拥有者，不能改后端重复执行。',usage:'估算不可替代实际费用',events:['start 回执未知','原提交核查中','外部效果未知，保留拥有权']},{id:'demo-record-private',owner:'demo-tester',scope:'payments-test',title:'不可枚举记录',status:'处理中',text:'不可见',events:[]}];
  const audit=[];
  let page='integrations',actor='config',scenario='unknown',notice='',preflight=null,userId='demo-tester',userDraft=null,recordId='demo-record-1',query='',lease=null,leaseDrafts={},memoryState='candidate',leaseTimer=null;
  const roles={config:'配置管理员',access:'权限管理员',support:'支持审阅员',approver:'审批责任人'};
  const scopes=['orders-test','orders-stage'];
  const button=(id,text,extra='')=>`<button type="button" data-service="${id}" ${extra}>${text}</button>`;
  const select=(label,key,value,items)=>`<label class="admin-field">${label}<select data-service-field="${key}">${items.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
  const input=(label,key,value,type='text')=>`<label class="admin-field">${label}<input type="${type}" data-service-field="${key}" value="${esc(value)}"></label>`;
  const toggle=(label,key,value)=>`<label class="admin-toggle"><span>${label}</span><input type="checkbox" data-service-field="${key}" ${value?'checked':''}></label>`;
  function log(action,target){audit.unshift({action,target,actor:roles[actor],at:new Date().toISOString()});}
  function navigation(active){return `<aside class="admin-sidebar"><a class="admin-brand" href="#admin-systems">◈ 平台管理</a><a class="admin-back" href="#chat">← 返回用户对话</a><div class="admin-nav-title">对话配置</div><nav class="admin-config-nav">${[['systems','系统配置'],['environments','环境配置'],['models','模型配置'],['permissions','权限配置']].map(([id,name])=>`<a href="#admin-${id}">${name}</a>`).join('')}</nav><div class="admin-nav-title service-nav-title">接入与治理</div><nav class="admin-service-nav">${Object.entries(pages).map(([id,[name]])=>`<a href="#admin-${id}" ${id===active?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="admin-secondary"><a href="#contract">设计与契约评审 ↗</a><a href="#approval">审批恢复演练 ↗</a><small>初始设计 · 离线演示<br>无真实接入与身份服务</small></div></aside>`;}
  function integrations(){return `<div class="service-three"><section class="service-card"><h2>模型访问</h2><p class="admin-muted">用户显示名来自模型预设，账号与密钥方式另行管理。</p>${select('账号管理方式','auth',settings.auth,[['agent_managed','Agent / 总控自行管理'],['secret_ref','受控宿主按引用注入']])}<dl><dt>凭据</dt><dd>${settings.auth==='agent_managed'?'只保存外部认证状态，不复制账号秘密':'仅保存秘密引用；原型无秘密值'}</dd><dt>数据出口</dt><dd>限定区域与服务目录；实际策略待验证</dd><dt>实际模型</dt><dd>未知，不能凭显示名称推断能力</dd></dl></section><section class="service-card"><h2>ACP 执行连接</h2>${select('协议支持分支','acpVersion',settings.acpVersion,[['v1','v1 · 当前设计基线'],['v2-draft','v2 · Draft，未准入']])}<dl><dt>生命周期</dt><dd>初始化 → 认证 → 新会话 → 事件 → 核查 / 停止</dd><dt>恢复与权限桥</dt><dd>逐能力发现；当前未验证</dd><dt>拥有者</dt><dd>固定 Binding，不透明切换后端</dd></dl></section><section class="service-card"><h2>MCP 工具连接</h2>${select('协议版本','mcpVersion',settings.mcpVersion,[['2026-07-28','2026-07-28'],['2025-11-25','2025-11-25 · 兼容分支']])}${select('传输','transport',settings.transport,[['streamable-http','Streamable HTTP'],['stdio','受控 stdio 子进程']])}<p class="admin-muted">两个 HTTP 版本的会话与流语义不同；不混用。工具清单、参数、风险、身份与预算分别检查。</p><span class="service-state">真实工具能力：未知</span></section></div><section class="service-card"><h2>接入条件预检</h2><p class="admin-muted">本地模拟策略检查，不探测端点，不安装或启动进程。</p>${select('演示故障','scenario',scenario,[['unknown','实际能力未知'],['schema','MCP schema 发生变化'],['bridge','审批桥接缺失'],['auth','认证已过期'],['scope','工具参数越界'],['timeout','工具调用结果未知'],['normal','设计条件齐全，仍待实测']])}${button('preflight','运行离线预检','class="admin-primary"')}${button('simulate-admission-change','模拟变更使当前计划失效')}<div id="service-preflight" role="status">${preflight?esc(preflight):'尚未运行预检。'}</div></section>`;}
  function runtime(){return `<div class="service-two"><section class="service-card"><h2>Agent 运行档案</h2><p class="admin-muted">业务环境：订单 / 测试。宿主模板：受控单 Agent。实际制品与隔离证据尚未配置。</p>${select('网络出口','network',settings.network,[['allowlist','仅登记的模型 / 资源服务'],['unrestricted','任意网络 · 禁止准入']])}${select('隔离证据','isolation',settings.isolation,[['unverified','未验证'],['design-only','仅策略草案，待实机证据']])}${toggle('允许受控代码读取','readCode',settings.readCode)}${toggle('允许写业务代码（本轮禁止）','writeCode',settings.writeCode)}${toggle('开放任意终端（本轮禁止）','terminal',settings.terminal)}<div class="admin-note">worktree 不是 OS 沙箱。原型不创建目录、不执行命令、不读取代码。</div></section><section class="service-card"><h2>代码与现场版本</h2>${input('代码快照（合成）','codeCommit',settings.codeCommit)}${input('现场部署版本（合成）','deployment',settings.deployment)}<div class="admin-resource"><span>允许范围</span><strong>登记仓库 / 固定 commit / 只读路径</strong><span>拒绝范围</span><strong>秘密文件、链接逃逸、跨租户目录</strong><span>证据定位</span><strong>repo / commit / path / 行号 / blobHash</strong><span>其他资源</span><strong>只读查询、脱敏日志、本会话附件</strong></div>${button('runtime-check','检查环境策略','class="admin-primary"')}<div id="runtime-result" role="status">${preflight&&page==='runtime'?esc(preflight):''}</div></section></div>`;}
  function context(){return `<div class="service-two"><section class="service-card"><h2>本轮上下文组装</h2>${input('总窗口预算（示例 token）','contextLimit',settings.contextLimit,'number')}${input('输出预留（示例 token）','outputReserve',settings.outputReserve,'number')}<ol class="service-list"><li>固定策略与操作计划</li><li>用户问题和明确条件</li><li>获准附件与当前版本代码证据</li><li>可追溯会话摘要</li><li>经审核且仍有效的记忆</li></ol>${button('context-check','生成合成材料清单','class="admin-primary"')}<div id="context-result" role="status">${preflight&&page==='context'?esc(preflight):''}</div><p class="admin-muted">实际模型窗口未知时仍阻断真实发送。过滤权限在检索之前，发出前再次核查。</p></section><section class="service-card"><h2>记忆策略</h2>${select('跨会话记忆','memory',settings.memory,[['off','默认关闭'],['personal','个人主动保存并审核'],['environment','系统环境范围 · 维护者审核']])}<p>合成条目：报表核对先对齐时间与状态。</p><dl><dt>来源</dt><dd>demo-record-1 / result-revision-1 · 合成</dd><dt>适用范围</dt><dd>订单 / 测试 · 原来源 ACL 仍有效才可用</dd><dt>条目状态</dt><dd id="memory-state">${esc(memoryState)}</dd></dl><div class="service-actions">${button('memory-review','审核候选')}${button('memory-activate','启用已审核条目')}${button('memory-revoke','撤销')}${button('memory-delete','请求删除')}${button('memory-source-revoke','模拟原来源撤权')}</div><p class="admin-muted">删除先进入 deletion_pending，待正文、索引、摘要及外部副本回执。不会把点击删除称为已经清除所有副本。</p></section></div>`;}
  function userPage(){const user=users.find(u=>u.id===userId);if(!userDraft||userDraft.id!==userId){userDraft=JSON.parse(JSON.stringify(user));if(userDraft.scopes===null)userDraft.scopes=[...(window.ConfigurationPrototype.current().roles.find(r=>r.id===user.role)?.environments||[])];}return `<div class="service-two"><section class="service-card"><h2>成员（合成）</h2>${users.map(u=>button('select-user',`${esc(u.name)} · ${u.status==='active'?'正常':'已暂停'}`,`data-id="${u.id}" class="service-record ${u.id===userId?'selected':''}"`)).join('')}<div class="admin-note">当前管理者可授予：订单 / 测试、订单 / 预发。不能借用户管理自行提权。</div></section><section class="service-card"><h2>${esc(user.name)}</h2><p class="admin-muted">${user.id} · 授权修订 ${user.revision} · 本页只改变合成用户样例。</p>${select('成员角色','userRole',userDraft.role,[['tester','测试人员'],['observer','协作成员'],['access','权限管理员（不可授予）']])}${['orders-test','orders-stage','payments-test'].map(id=>`<label class="admin-check"><input type="checkbox" data-user-scope="${id}" ${userDraft.scopes.includes(id)?'checked':''}>${esc(id)} ${scopes.includes(id)?'':'· 超出可授予范围'}</label>`).join('')}${input('变更理由 / 工单','reason',userDraft.reason||'')}<div class="service-actions">${button('save-user','预览权限变更','class="admin-primary"')}${button('toggle-user',user.status==='active'?'暂停该用户':'恢复该用户')}</div><p class="admin-muted">暂停阻止后续执行并触发撤权核查；真实在途动作是否停止需要权威回执。</p></section></div>`;}
  function recordPage(){const visible=['support','approver'].includes(actor)?[...records,...J.records()].filter(r=>r.scope==='orders-test'&&(!query||r.title.includes(query)||r.owner.includes(query))):[];const r=visible.find(x=>x.id===recordId);const canRead=!!(r&&lease&&lease.id===r.id&&lease.expires>Date.now()&&lease.actor===actor);return `<div class="service-two"><section class="service-card"><h2>获准范围内的问题记录</h2>${input('搜索标题或用户（合成）','query',query)}<p class="admin-muted">列表仅返回订单 / 测试范围的脱敏元数据。不可见记录不参与计数。</p>${visible.length?visible.map(x=>button('select-record',`${esc(x.title)} · ${esc(x.status)}`,`data-id="${x.id}" class="service-record"`)).join(''):'<p>无可访问记录，或当前演示角色无 records.list 权限。</p>'}</section><section class="service-card"><h2>记录详情</h2>${r?`<dl><dt>用户 / 范围</dt><dd>${esc(r.owner)} / ${esc(r.scope)}</dd><dt>状态 / 费用</dt><dd>${esc(r.status)} / ${esc(r.usage)}</dd></dl><h3>后台处理时间线（合成）</h3><ol class="service-list">${r.events.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><details><summary>配置与材料引用</summary><p>${esc(r.preparation?JSON.stringify({context:r.preparation.id,requestedModel:r.preparation.requestedModel,actualModel:r.preparation.actualModelId,code:r.preparation.codeSnapshot,mcp:r.preparation.mcpConnectionRef,memory:r.preparation.memoryRefs,binding:r.binding?.id,resultRevision:r.resultRevision}):'demo-runtime / demo-context-manifest / demo-code-commit / demo-mcp-schema')}</p></details>${actor==='approver'&&r.status==='待负责人审批'?button('approve-plan','审阅当前只读计划（合成）','class="admin-primary"'):''}<h3>正文审阅</h3>${input('审阅理由 / 工单','leaseReason',leaseDrafts[actor+':'+recordId]||'')}${button('lease','申请本条记录的短期审阅','class="admin-primary"')}${button('expire-lease','模拟租约过期')}<div id="record-content">${canRead?`<p class="service-sensitive">${esc(r.text)}</p><small>本次正文读取已记入合成审计。附件和下载仍需单独授权。</small>`:'<p class="admin-muted">正文尚未授权；元数据访问不包含正文和下载。</p>'}</div>`:'<p>请选择一条当前可访问的记录。</p>'}</section></div>`;}
  function render(next,focus=false){
    const target=pages[next]?next:'integrations';if(target!==page)preflight=null;page=target;root.dataset.mode='service';
    root.innerHTML=navigation(page)+`<main class="admin-main"><header class="admin-heading"><div><div class="admin-eyebrow">平台管理 / 接入与治理</div><h1 tabindex="-1">${pages[page][0]}</h1><p>${pages[page][1]}</p></div><span class="admin-badge">合成资料 · 设计评审</span></header><div class="service-role">${select('演示管理角色','actor',actor,Object.entries(roles))}<span>角色切换用于评审拒绝路径，不是登录鉴权。</span></div><div id="service-feedback" role="status" aria-live="polite">${esc(notice)}</div>${({integrations,runtime,context,users:userPage,records:recordPage})[page]()}<details class="admin-audit"><summary>本次合成治理审计（${audit.length}）</summary>${audit.map(a=>`<p>${esc(a.actor)} · ${esc(a.action)} · ${esc(a.target)} · ${a.at}</p>`).join('')||'<p>暂无操作。</p>'}</details></main><dialog id="service-dialog" aria-labelledby="service-dialog-title"></dialog>`;
    if(focus)root.querySelector('h1').focus();
    const dialog=root.querySelector('#service-dialog');dialog.addEventListener('cancel',()=>setTimeout(()=>root.querySelector('[data-service=save-user]')?.focus(),0));
  }
  const feedback=text=>{notice=text;root.querySelector('#service-feedback').textContent=text;};
  root.addEventListener('input',e=>{
    if(root.dataset.mode!=='service')return;const key=e.target.dataset.serviceField;
    if(!key||e.target.tagName==='SELECT'||e.target.type==='checkbox')return;
    if(key==='reason'){userDraft.reason=e.target.value;return;}
    if(key==='query'){query=e.target.value;return;}
    if(key==='leaseReason'){leaseDrafts[actor+':'+recordId]=e.target.value;return;}
    settings[key]=e.target.type==='number'?Number(e.target.value):e.target.value;preflight=null;
  });
  root.addEventListener('change',e=>{
    if(root.dataset.mode!=='service')return;const key=e.target.dataset.serviceField;
    if(e.target.dataset.userScope){const id=e.target.dataset.userScope;userDraft.scopes=e.target.checked?[...new Set([...userDraft.scopes,id])]:userDraft.scopes.filter(x=>x!==id);return;}
    if(!key||e.target.type!=='checkbox'&&e.target.tagName!=='SELECT')return;
    if(key==='actor'){actor=e.target.value;lease=null;notice='演示管理角色已切换，内容租约已失效。';}
    else if(key==='scenario')scenario=e.target.value;
    else if(key==='userRole')userDraft.role=e.target.value;
    else {settings[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='memory')J.updateMemory({mode:settings.memory});}
    preflight=null;render(page);
  });
  root.addEventListener('keydown',e=>{if(root.dataset.mode==='service'&&e.target.dataset.serviceField==='query'&&e.key==='Enter'){e.preventDefault();recordId='';render(page);}});
  root.addEventListener('click',e=>{
    if(root.dataset.mode!=='service')return;const b=e.target.closest('[data-service]');if(!b)return;const action=b.dataset.service;
    if(['preflight','runtime-check','context-check','memory-review','memory-activate','memory-revoke','memory-delete','memory-source-revoke'].includes(action)&&actor!=='config'){feedback('当前演示角色没有配置 / 记忆管理权限。');return;}
    if(action==='simulate-admission-change'){if(actor!=='config'){feedback('当前角色不能模拟接入变更。');return;}J.integrationChanged(scenario);log('接入观察变更，计划需复查',scenario);notice='已更新合成接入修订。旧计划失效，已有执行绑定保留。';render(page);return;}
    if(action==='preflight'){const failures={unknown:'阻断：实际模型与 Agent / MCP 能力未知。',schema:'阻断：工具 schema 摘要变化，需重新审核参数与计划。',bridge:'阻断：审批桥接未验证，不允许自动响应权限。',auth:'阻断：认证已过期，需责任人恢复认证。',scope:'阻断：工具参数超出允许环境或资源范围，不允许执行。',timeout:'结果未知：保留原 invocation 引用并核查，禁止新键重做。',normal:'设计条件齐全；真实认证、隔离、能力和执行仍未验证，不能真实启动。'};preflight=settings.acpVersion==='v2-draft'?'阻断：v2 为 Draft，适配器未准入。':failures[scenario];log('离线接入预检',scenario);render(page);return;}
    if(action==='runtime-check'){const blockers=[];if(settings.writeCode)blockers.push('禁止写业务代码');if(settings.terminal)blockers.push('禁止任意终端');if(settings.network!=='allowlist')blockers.push('禁止任意网络');if(!settings.codeCommit.trim()||!settings.deployment.trim())blockers.push('缺少固定版本');else if(settings.codeCommit!==settings.deployment)blockers.push('代码与部署版本不一致，只能给有限结论');blockers.push('真实隔离尚未验证');preflight='阻断：'+blockers.join('；');render(page);return;}
    if(action==='context-check'){const total=settings.contextLimit,reserve=settings.outputReserve;preflight=!Number.isInteger(total)||!Number.isInteger(reserve)||total<1||reserve<1||reserve>=total?'阻断：上下文预算必须为正整数，且需保留足够输入空间。':`合成清单：当前问题、获准代码片段和证据、来源可追溯摘要；长期记忆${settings.memory==='off'?'关闭':'仅限审核通过且原 ACL 仍有效的条目'}。输入预算 ${total-reserve}，输出预留 ${reserve}；真实模型窗口未知，实际发送仍阻断。`;render(page);return;}
    if(action==='memory-source-revoke'){J.updateMemory({sourceAccess:false});log(action,'demo-memory-1');notice='原来源已撤权，相关上下文、结果与正文租约失效。';render(page);return;}
    if(action==='memory-review'){if(memoryState!=='candidate'){feedback('只有候选条目可以审核。');return;}memoryState='reviewed';}
    if(action==='memory-activate'){if(memoryState!=='reviewed'){feedback('须先审核，再启用；候选和已撤销条目不可直接进入上下文。');return;}memoryState='active';}
    if(action==='memory-revoke')memoryState='revoked';
    if(action==='memory-delete')memoryState='deletion_pending';
    if(action.startsWith('memory-')){J.updateMemory({state:memoryState});log(action,'demo-memory-1');render(page);return;}
    if(action==='select-user'){userId=b.dataset.id;userDraft=null;render(page);return;}
    if(action==='save-user'||action==='toggle-user'){
      const u=users.find(x=>x.id===userId);if(actor!=='access'){feedback('当前演示角色没有 users.manage 权限。');return;}
      if(u.id==='demo-admin'){feedback('禁止修改自身身份或自行提权。');return;}
      if(!userDraft.reason||userDraft.reason.trim().length<5){feedback('请填写至少 5 字的变更理由 / 工单。');return;}
      if(userDraft.scopes.some(x=>!scopes.includes(x)&&!(u.scopes||window.ConfigurationPrototype.current().roles.find(r=>r.id===u.role)?.environments||[]).includes(x))||!['tester','observer'].includes(userDraft.role)){feedback('超出可授予的角色或环境范围。');return;}
      const dialog=root.querySelector('#service-dialog');dialog.innerHTML=`<h2 id="service-dialog-title">确认合成用户变更</h2><p>${esc(u.name)} · ${action==='toggle-user'?(u.status==='active'?'暂停后续使用':'恢复使用，不恢复旧批准'):esc(userDraft.role+' / '+userDraft.scopes.join(', '))}</p><p>理由：${esc(userDraft.reason)}</p>${button('cancel','继续编辑')}${button(action==='toggle-user'?'confirm-toggle':'confirm-save','确认变更','class="admin-primary"')}`;dialog.showModal();return;
    }
    if(action==='cancel'){root.querySelector('#service-dialog').close();return;}
    if(action==='confirm-save'||action==='confirm-toggle'){const u=users.find(x=>x.id===userId);if(actor!=='access'||u.id==='demo-admin'||userDraft.revision!==u.revision){feedback('变更权限或修订冲突，需重新检查。');return;}if(action==='confirm-save'){u.role=userDraft.role;u.scopes=[...userDraft.scopes];}else u.status=u.status==='active'?'suspended':'active';u.revision++;J.userChanged();log(action,u.id);lease=null;userDraft=null;notice='已更新合成用户样例；真实身份服务和在途撤权仍未实现。';render(page);return;}
    if(action==='approve-plan'){const r=J.records().find(x=>x.id===recordId);if(actor!=='approver'||r?.scope!=='orders-test'||r.status!=='待负责人审批'){feedback('无权处理此计划或计划已失效。');return;}const dialog=root.querySelector('#service-dialog');dialog.innerHTML=`<h2 id="service-dialog-title">确认这份只读计划？</h2><p>${esc(r.title)} / ${esc(r.scope)}<br>模型：${esc(r.preparation.requestedModel)}<br>上下文：${esc(r.preparation.id)}<br>固定输入修订：${r.preparation.inputRevision}；不包含写入。合成演示，不调用真实资源。</p>${button('cancel','取消')}${button('confirm-plan','批准这份计划','class="admin-primary"')}`;dialog.dataset.contextRef=r.preparation.id;dialog.showModal();return;}
    if(action==='confirm-plan'){const dialog=root.querySelector('#service-dialog');if(actor!=='approver'){feedback('当前角色不能审批此计划。');return;}const result=J.approve(recordId,dialog.dataset.contextRef);log('负责人计划审批',recordId);notice=result.ok?'负责人已确认本计划，等待合成结果；用户验收仍独立。':result.reason;render(page);return;}
    if(action==='select-record'){recordId=b.dataset.id;lease=null;render(page);return;}
    if(action==='lease'){const r=[...records,...J.records()].find(x=>x.id===recordId),reason=root.querySelector('[data-service-field=leaseReason]')?.value||'';if(actor!=='support'||r?.scope!=='orders-test'){feedback('当前角色或记录范围不允许正文审阅。');return;}if(reason.trim().length<5){feedback('需填写至少 5 字的用途理由 / 工单。');return;}lease={id:r.id,expires:Date.now()+5*60*1000,actor};clearTimeout(leaseTimer);leaseTimer=setTimeout(()=>{lease=null;notice='内容租约已自动到期，正文已隐藏。';if(root.dataset.mode==='service'&&page==='records')render(page);},5*60*1000);log('正文租约及读取：'+reason,r.id);notice='已取得本条合成记录的短期用途租约；不包含附件下载。';render(page);return;}
    if(action==='expire-lease'){lease=null;clearTimeout(leaseTimer);notice='内容租约已过期，正文不再显示。';render(page);}
  });
  J.subscribeRecords(()=>{if(root.dataset.mode==='service'&&page==='records')render(page);});
  window.ConfigurationPrototype.subscribe(()=>{if(lease){lease=null;clearTimeout(leaseTimer);notice='授权配置变化，正文租约已失效。';if(root.dataset.mode==='service'&&page==='records')render(page);}});
  J.subscribe(()=>{if(lease){lease=null;clearTimeout(leaseTimer);notice='授权或材料已变化，正文租约已失效。';}if(root.dataset.mode==='service'&&page==='records')render(page);});
  window.ServiceDesignPrototype={pages,navigation,render,inspect:()=>JSON.parse(JSON.stringify({settings,users,audit,memoryState,lease})),has:id=>Object.hasOwn(pages,id),hide(){lease=null;clearTimeout(leaseTimer);}};
})();
